#include <iiGUI/Presentation.h>
#include <iiGUI/PresentationBoundary.h>
#include <iiSDKCore/Runtime/EventLoop.h>
#include <iostream>
#include <stdexcept>
#include <thread>
#include <vector>
using namespace ii;
namespace {
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
auto at(int value){return runtime::Clock::time_point{}+std::chrono::milliseconds(value);}
core::ObservableSubscription observe(gui::PresentationStream& source,std::function<void(const gui::PresentationEvent&)> callback){auto r=source.observe(std::move(callback));if(!r)throw std::runtime_error(r.error().message);return std::move(*r);}
void defaults(){gui::PresentationStream s;check(!s.closed()&&!s.has_observers()&&s.sequence()==0&&s.observer_failures()==0,"Invalid presentation defaults");check(!s.observe({}),"Empty presentation observer admitted");}
void delivery(){gui::PresentationStream s;std::vector<gui::PresentationEvent> events;auto lease=observe(s,[&](const auto& e){events.push_back(e);});check(bool(s.queued(at(5),gui::GraphicsApi::metal))&&bool(s.queued(at(5),gui::GraphicsApi::metal)),"Presentation queue failed");check(events.size()==2&&events[0].sequence==1&&events[1].sequence==2&&events[1].timestamp==at(5)&&events[1].api==gui::GraphicsApi::metal&&s.sequence()==2,"Presentation metadata or duplicate-time delivery lost");}
void unsubscribe(){gui::PresentationStream s;int calls=0;auto lease=observe(s,[&](const auto&){++calls;});lease.reset();check(!s.has_observers()&&bool(s.queued(at(1),gui::GraphicsApi::none))&&calls==0,"Retired presentation callback delivered");}
void closure(){gui::PresentationStream s;int calls=0;auto lease=observe(s,[&](const auto& e){++calls;check(e.kind==gui::PresentationKind::closed&&s.closed(),"Close was not committed before notification");});s.close();s.close();auto r=s.queued(at(1),gui::GraphicsApi::none);check(calls==1&&!r&&r.error().code==core::ErrorCode::closed&&!s.observe([](const auto&){}),"Closed source admitted work or duplicate close");}
void owner(){gui::PresentationStream s;bool queue=false,subscription=false,read=false;std::thread t([&]{auto q=s.queued(at(1),gui::GraphicsApi::none);queue=!q&&q.error().code==core::ErrorCode::wrong_executor;auto r=s.observe([](const auto&){});subscription=!r&&r.error().code==core::ErrorCode::wrong_executor;try{(void)s.closed();}catch(const std::logic_error&){read=true;}});t.join();check(queue&&subscription&&read&&s.sequence()==0,"Foreign presentation operations changed state");}
void errors(){gui::PresentationStream s;int calls=0;auto throwing=observe(s,[](const auto&){throw std::runtime_error("observer");});auto next=observe(s,[&](const auto&){++calls;});auto r=s.queued(at(1),gui::GraphicsApi::metal);check(!r&&calls==1&&s.sequence()==1&&s.observer_failures()==1,"Presentation observer failure rolled back or skipped later observers");throwing.reset();check(bool(s.queued(at(2),gui::GraphicsApi::metal))&&calls==2,"Presentation did not recover");}
void reentrant(){gui::PresentationStream s;bool rejected=false;auto lease=observe(s,[&](const auto&){auto r=s.queued(at(3),gui::GraphicsApi::metal);rejected=!r&&r.error().code==core::ErrorCode::busy;});check(bool(s.queued(at(1),gui::GraphicsApi::metal))&&rejected&&s.sequence()==1,"Reentrant presentation admitted");}
void clock_sequence(){gui::PresentationStream s;check(bool(s.queued(at(2),gui::GraphicsApi::metal)),"Initial clock rejected");auto r=s.queued(at(1),gui::GraphicsApi::metal);check(!r&&r.error().code==core::ErrorCode::invalid_argument&&s.sequence()==1,"Backward clock changed stream");}
void close_in_callback(){auto source=std::make_shared<gui::PresentationStream>();std::vector<gui::PresentationKind> seen;auto lease=observe(*source,[&](const auto& e){seen.push_back(e.kind);if(e.kind==gui::PresentationKind::queued)source->close();});check(bool(source->queued(at(1),gui::GraphicsApi::metal))&&source->closed()&&seen==std::vector{gui::PresentationKind::queued,gui::PresentationKind::closed},"Callback close lost terminal event");}
void retirement(){core::ObservableSubscription lease;int closed=0;{auto source=std::make_unique<gui::PresentationStream>();lease=observe(*source,[&](const auto& e){closed+=e.kind==gui::PresentationKind::closed;});}check(closed==1&&!lease.active(),"Destroyed presentation source retained observer admission");}
void deferred(){runtime::EventLoop loop(8);gui::PresentationStream s([&](runtime::Task task){return loop.post(std::move(task));});int calls=0;auto lease=observe(s,[&](const auto&){++calls;});check(bool(s.queued(at(1),gui::GraphicsApi::metal))&&calls==0,"Deferred presentation ran in renderer");loop.poll();check(calls==1,"Presentation was not delivered by Core");}
void close_pending(){runtime::EventLoop loop(8);gui::PresentationStream s([&](runtime::Task task){return loop.post(std::move(task));});std::vector<gui::PresentationKind> seen;auto lease=observe(s,[&](const auto& e){seen.push_back(e.kind);});check(bool(s.queued(at(1),gui::GraphicsApi::metal)),"Deferred frame not admitted");s.close();loop.poll();check(seen==std::vector{gui::PresentationKind::closed},"Closed source retained pending delivery");}
void rebind(){runtime::EventLoop first(8),second(8);auto* current=&first;gui::PresentationStream s([&](runtime::Task task){return current->post(std::move(task));});int calls=0;auto lease=observe(s,[&](const auto&){++calls;});current=&second;check(bool(s.queued(at(1),gui::GraphicsApi::metal)),"Rebound source not admitted");first.poll();check(calls==0,"Presentation used retired host loop");second.poll();check(calls==1,"Rebound host loop lost presentation");}
void overload(){runtime::EventLoop loop(1);const auto occupied=loop.post([]{});gui::PresentationStream s([&](runtime::Task task){return loop.post(std::move(task));});std::string error;auto lease=observe(s,[&](const auto& e){error=e.error;});auto r=s.queued(at(1),gui::GraphicsApi::metal);check(!r&&s.closed()&&!error.empty()&&s.sequence()==0,"Queue overload silently lost telemetry");loop.poll();}
void inline_executor(){gui::PresentationStream s([](runtime::Task task){task();return runtime::Submission{};});int queued=0;auto lease=observe(s,[&](const auto& e){queued+=e.kind==gui::PresentationKind::queued;});check(!s.queued(at(1),gui::GraphicsApi::metal)&&s.closed()&&queued==0,"Inline executor entered renderer observer");}
void foreign_delivery(){runtime::EventLoop loop(8);runtime::Task pending;gui::PresentationStream s([&](runtime::Task task){pending=std::move(task);return loop.post([]{});});int calls=0;auto lease=observe(s,[&](const auto&){++calls;});check(bool(s.queued(at(1),gui::GraphicsApi::metal)),"Foreign fixture admission failed");std::thread t([&]{pending();});t.join();check(calls==0&&s.observer_failures()==1,"Foreign completion changed GUI state without diagnostic");loop.poll();}
void limits(){gui::PresentationStream s;std::vector<core::ObservableSubscription> leases;for(int i=0;i<1024;++i)leases.push_back(observe(s,[](const auto&){}));check(!s.observe([](const auto&){}),"Unbounded presentation observers");leases.back().reset();auto again=s.observe([](const auto&){});check(bool(again),"Expired observation did not return capacity");}
void boundary(){auto s=std::make_shared<gui::PresentationStream>();int calls=0;auto lease=observe(*s,[&](const auto&){++calls;});gui::GraphicsInfo info;info.api=gui::GraphicsApi::metal;gui::detail::draw_with_presentation(s,[&]{++info.frame_requests;},[&]{return info;},[]{return at(1);});check(calls==0,"Requested but unsubmitted frame counted");gui::detail::draw_with_presentation(s,[&]{++info.presentations;},[&]{return info;},[]{return at(2);});check(calls==1,"Accepted submission not counted");try{gui::detail::draw_with_presentation(s,[]{throw std::runtime_error("renderer");},[&]{return info;},[]{return at(3);});}catch(const std::runtime_error&){}check(calls==1,"Failed draw counted");}
void fallback(){auto s=std::make_shared<gui::PresentationStream>();int calls=0;auto lease=observe(*s,[&](const auto& e){++calls;check(e.api==gui::GraphicsApi::vulkan,"Fallback reported old renderer");});gui::GraphicsInfo info;info.api=gui::GraphicsApi::metal;info.presentations=50;gui::detail::draw_with_presentation(s,[&]{info.api=gui::GraphicsApi::vulkan;info.presentations=1;info.fallback_reason="native failure";},[&]{return info;},[]{return at(1);});check(calls==1,"Renderer counter reset lost fallback submission");}
void unobserved(){auto s=std::make_shared<gui::PresentationStream>();int draws=0,queries=0;gui::detail::draw_with_presentation(s,[&]{++draws;},[&]{++queries;return gui::GraphicsInfo{};},[]{return at(1);});check(draws==1&&queries==0&&s->sequence()==0,"Unobserved source queried telemetry or altered renderer admission");}

}
int main(int argc,char** argv){try{const std::string name=argc>1?argv[1]:"defaults";if(name=="defaults")defaults();else if(name=="delivery")delivery();else if(name=="unsubscribe")unsubscribe();else if(name=="closure")closure();else if(name=="owner")owner();else if(name=="errors")errors();else if(name=="reentrant")reentrant();else if(name=="clock")clock_sequence();else if(name=="close_in_callback")close_in_callback();else if(name=="retirement")retirement();else if(name=="deferred")deferred();else if(name=="close_pending")close_pending();else if(name=="rebind")rebind();else if(name=="overload")overload();else if(name=="inline_executor")inline_executor();else if(name=="foreign_delivery")foreign_delivery();else if(name=="limits")limits();else if(name=="boundary")boundary();else if(name=="fallback")fallback();else if(name=="unobserved")unobserved();else throw std::runtime_error("Unknown presentation case");std::cout<<"Presentation "<<name<<" passed\n";}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
